const TEMPLATES = {
  lembrete1: { name: 'outbound_lembrete_1', language: 'pt_BR', texto: 'Oi {{1}}, tudo bem? Fiquei sem retorno por aqui, mas sigo a disposicao se quiser continuar nossa conversa. Qualquer coisa, e so responder.' },
  lembrete2: { name: 'outbound_lembrete_2', language: 'pt_BR', texto: 'Oi {{1}}, passando para saber se ainda faz sentido conversarmos. Se puder, me da um retorno rapidinho, fico no aguardo.' },
  lembrete3: { name: 'outbound_lembrete_3', language: 'pt_BR', texto: 'Oi {{1}}, essa e a nossa ultima tentativa de contato por aqui. Se ainda tiver interesse, e so responder esta mensagem a qualquer momento.' },
};
return $input.all().map(({ json: c }) => {
  const tipo = c.tipo_envio;
  const tpl = TEMPLATES[tipo] || {};
  const nome = c.nome || '';
  const components = [{ type: 'body', parameters: [{ type: 'text', text: nome }] }];
  const texto = String(tpl.texto || '').replace(/\{\{\s*1\s*\}\}/g, nome);
  return { json: {
    ...c,
    template_name: tpl.name,
    texto_renderizado: texto,
    meta_body: {
      messaging_product: 'whatsapp',
      to: c.telefone,
      type: 'template',
      template: { name: tpl.name, language: { code: tpl.language || 'pt_BR' }, components },
    },
  }};
});

