insert into public."finamob-historico_mensagens"
  (nome_app, telefone, nome_usuario, mensagem_agente, message_type, ativo, entregue, enviado_manual)
values ('{{ $('Config Outbound').first().json.nome_app }}', $1, $2, $3, 'text', true, false, false);

update public.outbound_contatos
set etapa = 'falha', erro = left($2, 1000), proximo_fup_em = null, updated_at = now()
where id = $1::uuid and etapa = 'em_conversa';
